#!/usr/bin/env bash
# Human-runnable version of the clips generated by tests/test_media.py fixtures.
# Usage: make_clips.sh OUT_DIR
set -euo pipefail
out="${1:-.}"; mkdir -p "$out"
# 1080x1920 portrait HEVC .mov, 5 s (encoded portrait directly, no rotation matrix)
ffmpeg -y -v error -f lavfi -i "testsrc=size=1080x1920:rate=30:duration=5" \
  -c:v libx265 -pix_fmt yuv420p -tag:v hvc1 "$out/portrait_hevc.mov"
# 5 s solid colour clip
ffmpeg -y -v error -f lavfi -i "color=c=teal:size=320x240:rate=30:duration=5" \
  -c:v libx264 -pix_fmt yuv420p "$out/solid5.mp4"
# 200 s tiny low-fps clip (for the too_long check)
ffmpeg -y -v error -f lavfi -i "testsrc=size=64x64:rate=1:duration=200" \
  -c:v libx264 -pix_fmt yuv420p "$out/long200.mp4"
